css:
.newsletter {
  max-inline-size: 36rem;
  margin-inline: auto;
  padding: var(--va-space-inline-lg);
  font-family: var(--va-font-family-ui);
  color: var(--va-color-text-default);
  container-type: inline-size;
}

.newsletter h1 {
  margin: 0 0 var(--va-space-inline-md);
  font-family: var(--va-font-family-reading);
  font-size: var(--va-font-size-lg);
  font-weight: var(--va-font-weight-bold);
}

.newsletter-form {
  margin: 0;
}

/* Field and button side by side. The row aligns to the bottom edge, so the
   button lines up with the input box, not with the label above it. The help
   text and any error sit just below the field, in space reserved by the
   row's bottom padding, so they don't push the input out of line. */
.newsletter-row {
  display: flex;
  align-items: flex-end;
  gap: var(--va-space-gap-md);
  padding-block-end: calc(var(--va-font-size-sm) * 3 + var(--va-space-gap-sm));
}

.newsletter-email {
  position: relative;
  flex: 1 1 auto;
  min-inline-size: 0;
}

.newsletter-email::part(help),
.newsletter-email::part(error) {
  position: absolute;
  inset-block-start: calc(100% + var(--va-space-gap-sm));
  inset-inline: 0;
  margin: 0;
}

.newsletter-row > va-button {
  flex: 0 0 auto;
}

/* On narrow screens, stack the button under the field. */
@container (max-width: 24rem) {
  .newsletter-row {
    flex-direction: column;
    align-items: stretch;
    padding-block-end: 0;
  }

  .newsletter-email::part(help),
  .newsletter-email::part(error) {
    position: static;
  }
}

.newsletter-status {
  margin: 0;
  font-size: var(--va-font-size-sm);
  color: var(--va-color-text-muted);
}

.newsletter-status:empty {
  display: none;
}

js:
const form = document.getElementById('newsletter-form');
const email = document.getElementById('newsletter-email');
const submit = document.getElementById('newsletter-submit');
const status = document.getElementById('newsletter-status');

form.addEventListener('submit', async (event) => {
  event.preventDefault();
  status.textContent = '';

  if (!email.checkValidity()) {
    email.error = email.value.trim()
      ? 'Enter a valid email address, like ada@example.com.'
      : 'Enter your email address.';
    return;
  }

  email.error = '';
  submit.loading = true;

  try {
    // Replace with the real request to your newsletter service.
    await new Promise((resolve) => setTimeout(resolve, 600));
    status.textContent = `Thanks! We'll send the newsletter to ${email.value.trim()}.`;
    form.reset();
    email.value = '';
  } catch {
    email.error = "Couldn't subscribe you. Please try again.";
  } finally {
    submit.loading = false;
  }
});

// Clear a custom error as soon as the user edits the address.
email.addEventListener('input', () => {
  if (email.error) email.error = '';
});
